const rows = $('Get row(s) in sheet').all().map(item => item.json);

let params = {};
if (typeof query === 'object' && query !== null) {
 params = query;
} else if (typeof query === 'string' && query.trim().startsWith('{')) {
 try { params = JSON.parse(query); } catch (e) { params = {}; }
}

const norm = (v) => (v === undefined || v === null ? '' : v.toString()).toLowerCase();

// Splits a query into multiple search terms (on commas, "and", "&", "/", or plain spaces)
// so a combined multi-category ask like "bakery coffee" or "bakery and coffee shops"
// matches ANY of the terms instead of requiring the whole phrase as one substring.
const splitTerms = (s) => norm(s)
 .split(/,|\band\b|&|\//)
 .flatMap(part => part.trim().split(/\s+/))
 .map(t => t.trim())
 .filter(Boolean);

let results = rows;

if (params.city) {
 const q = norm(params.city);
 results = results.filter(r => norm(r.City).includes(q));
}

if (params.cuisine) {
 const terms = splitTerms(params.cuisine);
 results = results.filter(r => terms.some(q =>
 norm(r.Category).includes(q) ||
 norm(r['Place Name']).includes(q) ||
 norm(r.Notes).includes(q)
 ));
}

if (params.minRating !== undefined && params.minRating !== null && params.minRating !== '') {
 const min = parseFloat(params.minRating);
 if (!isNaN(min)) {
 results = results.filter(r => parseFloat(r.Rating) >= min);
 }
}

if (params.visited !== undefined && params.visited !== null && params.visited !== '') {
 const wantVisited = params.visited === true || params.visited === 'true';
 results = results.filter(r => {
 const v = norm(r['Visited?']);
 const isVisited = v === 'true' || v === 'yes' || v === 'y' || v === 'visited';
 return isVisited === wantVisited;
 });
}

if (params.keyword) {
 const terms = splitTerms(params.keyword);
 results = results.filter(r => terms.some(q =>
 norm(r['Place Name']).includes(q) ||
 norm(r.Category).includes(q) ||
 norm(r.Notes).includes(q) ||
 norm(r.City).includes(q) ||
 norm(r.Address).includes(q)
 ));
}

const output = results.slice(0, 15).map(r => ({
 name: r['Place Name'],
 category: r.Category,
 rating: r.Rating,
 reviews: r.Reviews,
 priceRange: r['Price Range'],
 visited: r['Visited?'],
 city: r.City,
 address: r.Address,
 notes: r.Notes
}));

return JSON.stringify({ count: output.length, totalSaved: rows.length, results: output });

parameters.inputSchema:
{
 "type": "object",
 "properties": {
 "city": {
 "type": "string",
 "description": "City or area to filter by, e.g. Santa Clara"
 },
 "cuisine": {
 "type": "string",
 "description": "Cuisine or category to filter by, e.g. Indian, pizza, cafe"
 },
 "minRating": {
 "type": "number",
 "description": "Minimum star rating, e.g. 4"
 },
 "maxPrice": {
 "type": "string",
 "description": "Maximum budget hint as text, e.g. cheap, $20-60. Leave blank unless user mentions budget"
 },
 "visited": {
 "type": "boolean",
 "description": "true to only show places already visited, false to only show places not yet visited, omit to include both"
 },
 "keyword": {
 "type": "string",
 "description": "Freeform keyword to search across place name, category, and notes, e.g. rooftop, date night, vegetarian"
 }
 },
 "required": []
}

